+pub(super) fn read_assembly(
+    def: &Value,
+    name: &str,
+    table: &[DocumentComponent],
+    version: Option<u64>,
+    body: Option<ToolBody>,
+) -> Result<(Option<LibraryAssembly>, Option<ToolBody>), String> {
+    let Some(raw) = def.get("assembly").filter(|v| !v.is_null()) else {
+        return Ok((None, body));
+    };
+    if let Some(v) = version
+        && v < ASSEMBLY_VERSION
+    {
