+        assert!(!row[2].contains('*') && !row[3].contains('*'), "a glob in {row:?}");
+        let scripts = ticked(&row[3], ".cps");
+        for s in &scripts {
+            assert!(root().join("assets/posts").join(s).is_file(), "{s} is not in assets/posts");
