+    let a = m.axis_rows().into_iter().find(|r| r.name == "A").expect("A row");
+    assert_eq!(a.axis, Some([0.0, 1.0, 0.0]));
+    assert_eq!(a.letter_note().as_deref(), Some("A turns about Y: by RS-274 an axis about Y is B"));
+    let a_ptr = a.pointer.clone();
