+fn find_axis<'a>(parts: &'a serde_json::Value, id: &str) -> Option<&'a serde_json::Value> {
+    for p in parts.as_array()? {
+        if p["name"] == id {
+            return Some(&p["travel"]);
+        }
+        if let Some(t) = find_axis(&p["parts"], id) {
+            return Some(t);
+        }
+    }
+    None
