+/// One INSERT record: a placed copy (or a grid of copies) of a block.
+#[derive(Clone, Debug)]
+pub struct InsertRef {
+    name: String,
+    layer: String,
+    at: [f64; 3],
+    scale: [f64; 3],
+    rotation_deg: f64,
+    columns: u32,
+    rows: u32,
+    spacing: [f64; 2],
+}
