+struct Definition<'a> {
+    name: String,
+    base: [f64; 3],
+    body: &'a str,
+}
+
+/// The block definitions of the BLOCKS section, by upper-case name (DXF names ignore case).
+#[derive(Default)]
+pub(super) struct Definitions<'a> {
+    blocks: BTreeMap<String, Definition<'a>>,
