+
+/// A SPLINE or ELLIPSE stays a curve until it is placed, then is fitted in world units.
+enum Item {
+    Primitive(LayeredPrimitive),
+    Curve(LayeredCurve),
+}
+
+impl Item {
+    fn layer(&self) -> &str {
+        match self {
+            Item::Primitive(p) => &p.layer,
+            Item::Curve(c) => &c.layer,
+        }
