+
+/// Merge the primitives and the deferred curves of a body in drawing order.
+fn items(primitives: Vec<LayeredPrimitive>, curves: Vec<LayeredCurve>) -> Vec<Item> {
+    let mut out = Vec::with_capacity(primitives.len() + curves.len());
