+            let placed = curve.mapped(|p| m.point(p, context))?;
+            let out = spline_arcs(state, &placed).map_err(|e| DxfError(format!("{context}: {}", e.0)))?;
+            if out.is_empty() {
+                return Err(error(context, "placed curve has zero length"));
+            }
+            Ok(out)
+        }
+    }
+}

