+    m: [f64; 4],
+    t: [f64; 2],
+    sz: f64,
+    tz: f64,
+}
+
+impl Affine {
+    pub const IDENTITY: Self = Self { m: [1.0, 0.0, 0.0, 1.0], t: [0.0, 0.0], sz: 1.0, tz: 0.0 };
