+    /// The map `p -> at + M (p - base)`, Z by `at_z + sz (z - base_z)`.
+    pub fn insert(m: [f64; 4], at: [f64; 3], sz: f64, base: [f64; 3]) -> Self {
+        let [a, b, c, d] = m;
+        Self {
+            m,
+            t: [at[0] - (a * base[0] + b * base[1]), at[1] - (c * base[0] + d * base[1])],
