+    for w in pts.windows(2) {
+        let len = dist(w[0], w[1]);
+        if len <= 1e-9 {
+            continue;
+        }
+        let (tx, ty) = ((w[1].x - w[0].x) / len, (w[1].y - w[0].y) / len);
+        let fl = Point2::new(w[1].x - ty * f, w[1].y + tx * f);
+        let fr = Point2::new(w[1].x + ty * f, w[1].y - tx * f);
+        if !cleared(fl) && !cleared(fr) {
+            return true;
+        }
+    }
+    false
