+/// facet nearer than `stop` is found (a caller asking "at least
+/// `stop`?" needs no more). `v` zero reads the segment `o -> o + u`.
+pub(super) fn quad_gap(
+    o: Point3,
+    u: Point3,
+    v: Point3,
+    facets: &[Triangle],
+    boxes: &[[f64; 6]],
+    cap: f64,
+    stop: f64,
