+    // contour chains exactly.
+    let mut here = first;
+    for (i, m) in ring.iter().enumerate() {
+        let Some(p2) = pts.get(i + 1) else {
+            return Err(refused(mode, format!("lost pass {n}'s contour")));
+        };
