+#[test]
+fn a_circle_is_programmed_as_arcs_at_the_part_radius() {
+    let r = 2.335;
+    let c = Point2::new(0.0, 0.0);
+    let moves = vec![
+        feed((0.0, 0.0), (r, 0.0)),
+        feed((r, 0.0), (-r, 0.0)).with_arc(c, true),
+        feed((-r, 0.0), (r, 0.0)).with_arc(c, true),
