+fn tri(a: (f64, f64, f64), b: (f64, f64, f64), c: (f64, f64, f64)) -> Triangle {
+    Triangle::new(p3(a.0, a.1, a.2), p3(b.0, b.1, b.2), p3(c.0, c.1, c.2))
