+fn floor_under_a_canopy() -> Vec<Triangle> {
+    let mut f = vec![tri((0.0, 0.0, 0.0), (40.0, 0.0, 0.0), (40.0, 30.0, 0.0)), tri((0.0, 0.0, 0.0), (40.0, 30.0, 0.0), (0.0, 30.0, 0.0))];
