+        "{msg}"
+    );
+    let at = e.location().expect("the refusal names its spot");
+    assert!(
+        (at.x - R_ROOT).abs() < 1e-6 && at.y.abs() < 1e-6 && (at.z - 2.0).abs() < 1e-6,
