+        let sign = if self.arc.is_some_and(|(_, ccw)| ccw) { 1.0 } else { -1.0 };
+        (0..n)
+            .map(|k| {
+                let (s, co) = (sign * sweep * k as f64 / n as f64).sin_cos();
+                [c[0] + co * a[0] - s * a[1], c[1] + s * a[0] + co * a[1]]
+            })
+            .collect()
+    }
+}

