+    (SK30, &[(3.0, 80.0), (4.0, 80.0), (5.0, 80.0), (6.0, 80.0), (8.0, 80.0), (10.0, 80.0), (12.0, 80.0), (14.0, 80.0), (16.0, 80.0), (20.0, 80.0)]),
