+fn inside(t: &Tool, pts: &[[f64; 2]], what: &str) {
+    for p in pts {
+        assert!(p[0] <= reach(t, p[1]) + 1e-6, "{what}: ({:.4}, {:.4}) is outside the tool {:.4}", p[0], p[1], reach(t, p[1]));
+    }
