+    for ic in [12.0, 12.7] {
+        let r = 0.5 * ic;
+        let pts: Vec<[f64; 2]> = (0..=720)
+            .map(|i| {
+                let (s, c) = (std::f64::consts::TAU * f64::from(i) / 720.0).sin_cos();
+                [16.0 - r + r * c, r + r * s]
+            })
