+/// The 4-seat face mill rig of the SCMT12 square insert.
+fn assembly(seat_d: f64, body_r: f64) -> Vec<AssemblyNode> {
+    rig("SSDCN2525M12", &even(seat_d), 40.0, body_r, "SCMT120408")
